        self.in_events_section = False
        self.current_event_type = None
        self.current_argument_role = None


class PositionDetector:
    """Detects current field position by parsing generated text.

    Regex-based parsing of JSON text generated so far. Called at every
    decoding step, so only inspects the tail of the text.
    """

    # ── RE patterns (existing) ──
    _RE_TAIL_TYPE = re.compile(r'"tail_type"\s*:\s*"[^"]*$')
    _RE_HEAD_TYPE = re.compile(r'"head_type"\s*:\s*"[^"]*$')
    _RE_TYPE_FIELD = re.compile(r'"type"\s*:\s*"[^"]*$')

    _RE_ENTITY = re.compile(r'"text"\s*:\s*"([^"]+)"\s*,\s*"type"\s*:\s*"([^"]+)"')

    _RE_REL_TYPE_VAL = re.compile(r'"type"\s*:\s*"([^"]+)"')
    _RE_HEAD_TYPE_VAL = re.compile(r'"head_type"\s*:\s*"([^"]+)"')
    _RE_HEAD_TEXT_VAL = re.compile(r'"head"\s*:\s*"([^"]+)"')
    _RE_TAIL_TEXT_VAL = re.compile(r'"tail"\s*:\s*"([^"]+)"')
    _RE_REL_START = re.compile(r'\{\s*"head"')

    # ── EE patterns (new) ──
    _RE_EVENT_TYPE_POS = re.compile(r'"event_type"\s*:\s*"[^"]*$')
    _RE_ROLE_POS = re.compile(r'"role"\s*:\s*"[^"]*$')
    _RE_ARG_ENTITY_TYPE_POS = re.compile(r'"entity_type"\s*:\s*"[^"]*$')

    _RE_EVENT_START = re.compile(r'\{\s*"trigger"')
    _RE_EVENT_TYPE_VAL = re.compile(r'"event_type"\s*:\s*"([^"]+)"')
    _RE_ARG_START = re.compile(r'\{\s*"text"\s*:\s*"[^"]*"\s*,\s*"role"')
    _RE_ROLE_VAL = re.compile(r'"role"\s*:\s*"([^"]+)"')

    @classmethod
    def detect(cls, generated_text: str, state: GenerationState) -> FieldPosition:
        """Determine which JSON field is currently being generated.

        Mutates state in place: updates entity registry, current relation type,
        current head type, event type, argument role, etc.
        """
        if '"relations"' in generated_text:
            state.in_entities_section = False

        if '"events"' in generated_text:
            state.in_entities_section = False
            state.in_events_section = True

        # Register entities from the entities section
        for match in cls._RE_ENTITY.finditer(generated_text):
            state.entity_registry.register(match.group(1), match.group(2))

        # ── RE state tracking ──
        last_rel_start = -1
        for m in cls._RE_REL_START.finditer(generated_text):
            last_rel_start = m.start()

        if last_rel_start >= 0:
            partial_rel = generated_text[last_rel_start:]

            m = cls._RE_REL_TYPE_VAL.search(partial_rel)
            if m:
                state.current_relation_type = m.group(1)

            m = cls._RE_HEAD_TYPE_VAL.search(partial_rel)
            if m:
                state.current_head_type = m.group(1)

            m = cls._RE_HEAD_TEXT_VAL.search(partial_rel)
            if m:
                state.current_head_text = m.group(1)

            m = cls._RE_TAIL_TEXT_VAL.search(partial_rel)
            if m:
                state.current_tail_text = m.group(1)

        # ── EE state tracking ──
        last_event_start = -1
        for m in cls._RE_EVENT_START.finditer(generated_text):
            last_event_start = m.start()

        if last_event_start >= 0:
            partial_event = generated_text[last_event_start:]

            m = cls._RE_EVENT_TYPE_VAL.search(partial_event)
            if m:
                state.current_event_type = m.group(1)
            else:
                state.current_event_type = None

            # Find last argument object within current event
            last_arg_start = -1
            for m in cls._RE_ARG_START.finditer(partial_event):
                last_arg_start = m.start()

            if last_arg_start >= 0:
                partial_arg = partial_event[last_arg_start:]
                m = cls._RE_ROLE_VAL.search(partial_arg)
                if m:
                    state.current_argument_role = m.group(1)
                else:
                    state.current_argument_role = None
            else:
                state.current_argument_role = None

        # ── Position detection from tail ──
        tail = generated_text[-100:]

        # EE positions (check first, more specific field names)
        if cls._RE_EVENT_TYPE_POS.search(tail):
            return FieldPosition.EVENT_TYPE

        if cls._RE_ARG_ENTITY_TYPE_POS.search(tail):
            return FieldPosition.ARGUMENT_ENTITY_TYPE

        if state.in_events_section and cls._RE_ROLE_POS.search(tail):
            return FieldPosition.ARGUMENT_ROLE

        # RE positions
        if cls._RE_TAIL_TYPE.search(tail):
            return FieldPosition.RELATION_TAIL_TYPE

        if cls._RE_HEAD_TYPE.search(tail):
            return FieldPosition.RELATION_HEAD_TYPE

        if cls._RE_TYPE_FIELD.search(tail):
            if state.in_entities_section:
                return FieldPosition.ENTITY_TYPE
            else:
                return FieldPosition.RELATION_TYPE

        return FieldPosition.FREE_TEXT


class TypeConstraintProcessor(LogitsProcessor):
    """Enforces semantic type constraints during autoregressive generation.

    RE mode constraints:
    - ENTITY_TYPE: Allow all entity type first tokens (defense-in-depth)
    - RELATION_HEAD_TYPE: Given relation R, allow types valid as head
    - RELATION_TAIL_TYPE: Given (R, head_type), allow valid tail types

    EE mode constraints:
    - EVENT_TYPE: Allow all event type first tokens
    - ARGUMENT_ROLE: Given event_type, allow only valid roles
    - ARGUMENT_ENTITY_TYPE: Given (event_type, role), allow valid entity types

    Mode is auto-detected from ConstraintSpec.has_event_constraints.
    """

    def __init__(
        self,
        spec: ConstraintSpec,
        tokenizer: PreTrainedTokenizerBase,
        prompt_length: int = 0,
    ):
        self.spec = spec
        self.tokenizer = tokenizer
        self.prompt_length = prompt_length
        self.state = GenerationState()
        self.detector = PositionDetector()

        self._type_first_token, self._all_type_first_tokens = (
            self._build_first_token_map()
        )

        # EE-specific maps (empty if RE mode)
        self._event_type_first_token: dict[str, int] = {}
        self._role_first_token: dict[str, int] = {}
        if spec.has_event_constraints:
            self._event_type_first_token = self._build_event_type_map()
            self._role_first_token = self._build_role_map()

    def _build_first_token_map(self) -> tuple[dict[str, int], set[int]]:
        """Build entity_type -> first_token_id mapping.

        Uses pre-computed token IDs from ConstraintSpec if available,
        otherwise falls back to tokenizer.encode().
        """
        type_first_token: dict[str, int] = {}
        all_first_tokens: set[int] = set()

        for etype in self.spec.entity_types:
            if etype in self.spec.entity_type_first_token:
                first_id = self.spec.entity_type_first_token[etype]
            else:
                token_ids = self.spec.entity_type_token_ids.get(etype)
                if token_ids is None:
                    token_ids = self.tokenizer.encode(etype, add_special_tokens=False)
                first_id = token_ids[0]

            type_first_token[etype] = first_id
            all_first_tokens.add(first_id)

        return type_first_token, all_first_tokens

    def _build_event_type_map(self) -> dict[str, int]:
        """Build event_type -> first_token_id mapping."""
        result: dict[str, int] = {}
        for etype in self.spec.event_types:
            if etype in self.spec.event_type_first_token:
                result[etype] = self.spec.event_type_first_token[etype]
            else:
                token_ids = self.spec.event_type_token_ids.get(etype)
                if token_ids is None:
                    token_ids = self.tokenizer.encode(etype, add_special_tokens=False)
                result[etype] = token_ids[0]
        return result

    def _build_role_map(self) -> dict[str, int]:
        """Build role -> first_token_id mapping."""
        result: dict[str, int] = {}
        for role in self.spec.all_roles:
            if role in self.spec.role_first_token:
                result[role] = self.spec.role_first_token[role]
            else:
                token_ids = self.spec.role_token_ids.get(role)
                if token_ids is None:
                    token_ids = self.tokenizer.encode(role, add_special_tokens=False)
                result[role] = token_ids[0]
        return result

    def _detect_position(self, generated_text: str) -> FieldPosition:
        """Detect current token's semantic position in the JSON structure."""
        return self.detector.detect(generated_text, self.state)

    def __call__(
        self,
        input_ids: torch.LongTensor,
        scores: torch.FloatTensor,
    ) -> torch.FloatTensor:
        """Apply semantic constraints to logits.

        Args:
            input_ids: [batch_size, seq_len] -- full sequence including prompt
            scores: [batch_size, vocab_size] -- logits for next token

        Returns:
            Modified scores with disallowed type tokens set to -inf
        """
        batch_size = input_ids.shape[0]

        for batch_idx in range(batch_size):
            generated_ids = input_ids[batch_idx, self.prompt_length:].tolist()
            generated_text = self.tokenizer.decode(
                generated_ids, skip_special_tokens=True
            )

            position = self._detect_position(generated_text)

            if position == FieldPosition.ENTITY_TYPE:
                scores[batch_idx] = self._mask_entity_type(scores[batch_idx])

            elif position == FieldPosition.RELATION_HEAD_TYPE:
                scores[batch_idx] = self._mask_head_type(scores[batch_idx])

            elif position == FieldPosition.RELATION_TAIL_TYPE:
                scores[batch_idx] = self._mask_tail_type(scores[batch_idx])

            elif position == FieldPosition.EVENT_TYPE:
                scores[batch_idx] = self._mask_event_type(scores[batch_idx])

            elif position == FieldPosition.ARGUMENT_ROLE:
                scores[batch_idx] = self._mask_argument_role(scores[batch_idx])

            elif position == FieldPosition.ARGUMENT_ENTITY_TYPE:
                scores[batch_idx] = self._mask_argument_entity_type(
                    scores[batch_idx]
                )

        return scores

    # ── RE mask functions ────────────────────────────────────────────────

    def _mask_entity_type(self, logits: torch.FloatTensor) -> torch.FloatTensor:
        """At entity type position, allow only valid entity type first tokens."""
        return self._apply_type_mask(logits, set(self.spec.entity_types))

    def _mask_head_type(self, logits: torch.FloatTensor) -> torch.FloatTensor:
        """Mask entity types that cannot be head_type for the current relation."""
        rel_type = self.state.current_relation_type
        constraint = self.spec.get_constraint(rel_type) if rel_type else None
        allowed_dr = constraint.valid_head_types() if constraint else None

        head_text = self.state.current_head_text
        if head_text:
            actual_type = self.state.entity_registry.get_type(head_text)
            if actual_type and actual_type in self._type_first_token:
                if allowed_dr is None or actual_type in allowed_dr:
                    return self._apply_type_mask(logits, {actual_type})

        if allowed_dr is not None:
            return self._apply_type_mask(logits, allowed_dr)
        return logits

    def _mask_tail_type(self, logits: torch.FloatTensor) -> torch.FloatTensor:
        """Mask entity types that cannot be tail_type for (relation, head_type)."""
        rel_type = self.state.current_relation_type
        head_type = self.state.current_head_type
        constraint = self.spec.get_constraint(rel_type) if rel_type else None

        if constraint is not None:
            if head_type is not None:
                allowed_dr = constraint.valid_tail_types_for_head(head_type)
            else:
                allowed_dr = constraint.valid_tail_types()
        else:
            allowed_dr = None

        tail_text = self.state.current_tail_text
        if tail_text:
            actual_type = self.state.entity_registry.get_type(tail_text)
            if actual_type and actual_type in self._type_first_token:
                if allowed_dr is None or actual_type in allowed_dr:
                    return self._apply_type_mask(logits, {actual_type})

        if allowed_dr is not None:
            return self._apply_type_mask(logits, allowed_dr)
        return logits

    # ── EE mask functions ────────────────────────────────────────────────

    def _mask_event_type(self, logits: torch.FloatTensor) -> torch.FloatTensor:
        """At event_type position, allow all valid event type first tokens."""
        if not self._event_type_first_token:
            return logits
        return self._apply_first_token_mask(
            logits, self._event_type_first_token, set(self.spec.event_types)
        )

    def _mask_argument_role(self, logits: torch.FloatTensor) -> torch.FloatTensor:
        """At argument role position, allow only valid roles for current event_type."""
        if not self._role_first_token:
            return logits

        event_type = self.state.current_event_type
        if event_type:
            valid_roles = self.spec.get_valid_roles(event_type)
            if valid_roles:
                return self._apply_first_token_mask(
                    logits, self._role_first_token, valid_roles
                )

        # No event_type context: allow all roles
        return self._apply_first_token_mask(
            logits, self._role_first_token, set(self.spec.all_roles)
        )

    def _mask_argument_entity_type(
        self, logits: torch.FloatTensor
    ) -> torch.FloatTensor:
        """At argument entity_type position, constrain by (event_type, role)."""
        event_type = self.state.current_event_type
        role = self.state.current_argument_role

        if event_type and role:
            valid_types = self.spec.get_valid_entity_types_for_role(event_type, role)
            if valid_types:
                return self._apply_type_mask(logits, valid_types)

        # Fallback: allow all entity types
        return self._apply_type_mask(logits, set(self.spec.entity_types))

    # ── Shared mask utilities ────────────────────────────────────────────

    def _apply_type_mask(
        self,
        logits: torch.FloatTensor,
        allowed_types: set[str],
    ) -> torch.FloatTensor:
        """Set logits of disallowed entity type first-tokens to -inf.

        Only masks the FIRST token of each type string. XGrammar's grammar
        ensures remaining tokens are forced once the first is selected.
        """
        disallowed_first_tokens = [
            tid for etype, tid in self._type_first_token.items()
            if etype not in allowed_types
        ]

        if disallowed_first_tokens:
            logits[disallowed_first_tokens] = float("-inf")

        return logits

    def _apply_first_token_mask(
        self,
        logits: torch.FloatTensor,
        token_map: dict[str, int],
        allowed: set[str],
    ) -> torch.FloatTensor:
        """Generic first-token masking for any token_map (event types, roles, etc.)."""
        disallowed = [
            tid for name, tid in token_map.items()
            if name not in allowed
        ]

        if disallowed:
            logits[disallowed] = float("-inf")

        return logits

    def reset(self):
        """Reset state between generate() calls."""
        self.state.reset()


# ── Integration Helper ───────────────────────────────────────────────────

def build_constrained_processors(
    constraints_path: str,
    tokenizer: PreTrainedTokenizerBase,
    prompt_length: int,
) -> list[LogitsProcessor]:
    """Build the complete LogitsProcessor stack for constrained generation.

    Returns a list suitable for LogitsProcessorList:
        [xgrammar_processor, type_constraint_processor]

    Usage:
        processors = build_constrained_processors(
            "ontology_constraints.json", tokenizer, len(input_ids[0])
        )
        output = model.generate(**inputs, logits_processor=processors)
    """
    import xgrammar as xgr
    from .ontology_compiler import compile_ontology

    spec, compiled_grammar = compile_ontology(constraints_path, tokenizer)

    processors = []

    if compiled_grammar is not None:
        grammar_processor = xgr.contrib.hf.LogitsProcessor(compiled_grammar)
        processors.append(grammar_processor)

    type_processor = TypeConstraintProcessor(spec, tokenizer, prompt_length)
    processors.append(type_processor)

    return processors
